validator:
function validate(input) {
  const [{ Experiments = [] }] = input;
  const platforms = ['Android', 'IOS', 'Web'], names = ['Reading', 'Sports', 'Programming'];
  const ids = new Set();
  for (const [id, platform, name] of Experiments) {
    if (id === null || platform === null || name === null) return 'Every column is required.';
    if (ids.has(id)) return `experiment_id ${id} appears twice.`;
    ids.add(id);
    if (!platforms.includes(platform)) return `Unknown platform ${platform}.`;
    if (!names.includes(name)) return `Unknown experiment_name ${name}.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const platforms = ['Android', 'IOS', 'Web'], names = ['Reading', 'Sports', 'Programming'];
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  // Small sets favour a few combinations so that some pairs repeat and others stay empty.
  const pPool = size === 'small' ? platforms.slice(0, 1 + Math.floor(rand() * 3)) : platforms;
  const nPool = size === 'small' ? names.slice(Math.floor(rand() * 2)) : names;
  const Experiments = [];
  let id = 1 + Math.floor(rand() * 5);
  for (let i = 0; i < rows; i++) {
    Experiments.push([id, pPool[Math.floor(rand() * pPool.length)], nPool[Math.floor(rand() * nPool.length)]]);
    id += 1 + Math.floor(rand() * 3);
  }
  return [{ Experiments }];
}
